p-binary-search.starter:
def binary_search(nums: list[int], target: int) -> int:
    """Index of target in the sorted list nums, or -1. O(log n), without the bisect module."""
    raise NotImplementedError

p-binary-search.solution:
def binary_search(nums: list[int], target: int) -> int:
    lo, hi = 0, len(nums) - 1
    while lo <= hi:                  # nums[lo..hi] is the part that can still hold the target
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1             # everything up to mid is too small
        else:
            hi = mid - 1             # everything from mid on is too big
    return -1

p-find-the-first-and-last-position-of-an.starter:
def search_range(nums: list[int], target: int) -> list[int]:
    """[first, last] index of target in the sorted list nums, or [-1, -1]. O(log n), without the bisect module."""
    raise NotImplementedError

p-find-the-first-and-last-position-of-an.solution:
def lower_bound(nums: list[int], target: int) -> int:
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

def upper_bound(nums: list[int], target: int) -> int:
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] <= target:          # the only difference: <= instead of <
            lo = mid + 1
        else:
            hi = mid
    return lo

def search_range(nums: list[int], target: int) -> list[int]:
    first = lower_bound(nums, target)
    if first == len(nums) or nums[first] != target:
        return [-1, -1]
    return [first, upper_bound(nums, target) - 1]

