p-search-in-a-rotated-sorted-array.starter:
def search_rotated(nums: list[int], target: int) -> int:
    """Index of target in a rotated sorted list of distinct values, or -1. O(log n)."""
    raise NotImplementedError

p-search-in-a-rotated-sorted-array.solution:
def search_rotated(nums: list[int], target: int) -> int:
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[lo] <= nums[mid]:                      # left half nums[lo..mid] is sorted
            if nums[lo] <= target < nums[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:                                          # right half nums[mid..hi] is sorted
            if nums[mid] < target <= nums[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1

