p-generate-parentheses.starter:
def generate_parenthesis(n: int) -> list[str]:
    """Every balanced string of n pairs of parentheses, in the order shown in the examples."""
    raise NotImplementedError

p-generate-parentheses.solution:
def generate_parenthesis(n: int) -> list[str]:
    result: list[str] = []

    def explore(current: str, opened: int, closed: int) -> None:
        if len(current) == 2 * n:
            result.append(current)
            return
        if opened < n:
            explore(current + "(", opened + 1, closed)
        if closed < opened:
            explore(current + ")", opened, closed + 1)

    explore("", 0, 0)
    return result

