p-longest-increasing-subsequence.solution:
from bisect import bisect_left

def length_of_lis(nums: list[int]) -> int:
    tails: list[int] = []                   # tails[k] = smallest tail of an increasing run of length k + 1
    for x in nums:
        i = bisect_left(tails, x)           # bisect_left keeps it strictly increasing
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

p-longest-increasing-subsequence.reference:
from bisect import bisect_left

def length_of_lis_quadratic(nums: list[int]) -> int:
    if not nums:
        return 0
    dp = [1] * len(nums)                    # dp[i] = longest increasing subsequence ending at i
    for i in range(len(nums)):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def length_of_lis(nums: list[int]) -> int:
    tails: list[int] = []                   # tails[k] = smallest tail of an increasing run of length k + 1
    for x in nums:
        i = bisect_left(tails, x)           # bisect_left keeps it strictly increasing
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

for nums, expected in [([10, 9, 2, 5, 3, 7, 101, 18], 4), ([0, 1, 0, 3, 2, 3], 4), ([7, 7, 7, 7], 1), ([], 0), ([1, 2, 3], 3)]:
    assert length_of_lis(nums) == expected == length_of_lis_quadratic(nums)

p-unique-paths.starter:
def unique_paths(m: int, n: int) -> int:
    """Paths from the top-left to the bottom-right of an m x n grid, moving only right or down."""
    raise NotImplementedError

p-unique-paths.solution:
def unique_paths(m: int, n: int) -> int:
    row = [1] * n                       # the first row: one way to reach each cell
    for _ in range(1, m):
        for c in range(1, n):
            row[c] += row[c - 1]        # from above (old row[c]) + from the left (new row[c-1])
    return row[-1]

p-word-break.starter:
def word_break(s: str, word_dict: list[str]) -> bool:
    """True if s can be split into a sequence of words from word_dict (words may be reused)."""
    raise NotImplementedError

p-word-break.solution:
def word_break(s: str, word_dict: list[str]) -> bool:
    words = set(word_dict)
    longest = max(map(len, words), default=0)
    ok = [True] + [False] * len(s)              # ok[i]: s[:i] can be split into words
    for i in range(1, len(s) + 1):
        for j in range(max(0, i - longest), i):
            if ok[j] and s[j:i] in words:
                ok[i] = True
                break
    return ok[len(s)]

p-longest-common-subsequence.starter:
def longest_common_subsequence(a: str, b: str) -> int:
    """Length of the longest subsequence common to a and b."""
    raise NotImplementedError

p-longest-common-subsequence.solution:
def longest_common_subsequence(a: str, b: str) -> int:
    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]     # dp[i][j] = LCS of a[:i] and b[:j]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[n][m]

